cssHead:
body {
  background-color: #F9FAF7;
  font-family: 'Geist', sans-serif;
  -webkit-font-smoothing: antialiased;
}
.mia-sphere {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #a8c7b8 0%, #4f8069 45%, #203e35 85%, #12241f 100%);
  box-shadow: 0 4px 14px rgba(32, 62, 53, 0.22), inset 0 2px 4px rgba(255, 255, 255, 0.45);
}
